    }
  ],
  "seasonal_staffing_context": {
    "facts": [
      "Two summer seasonal employees left before September; their replacements were still learning.",
      "Three housekeeping workers were scheduled for the incident day; only Eka and Salome attended.",
      "Maia had retained a small permanent team but had not secured paid standby cover for harvest weekends.",
      "Maia arranged substantial reception overlap, but had not defined a consistent handover for conditional early-arrival requests."
    ],
    "gm_accountability": "I knew we were thin. I also approved a late checkout without checking what reception had already suggested to the next guest. That is not something I can put entirely on Luka."
  },
  "incident": {
    "date": "2026-09-19",
    "title": "Two early-room assurances during a short-staffed Saturday turnover",
    "inventory": {
      "previous_night_occupied_rooms": 17,
      "departures": 9,
      "stayover_rooms": 8,
      "arrival_room_bookings": 9,
      "occupied_rooms_that_night": 17,
      "occupancy_percent_rounded": 94.4,
      "remaining_room": "Room 18 was a clean single; neither affected two-person booking accepted it as a suitable substitute."
    },
    "affected_bookings": [
      {
        "id": "VC-0919-06",
        "assigned_room": "06",
        "party": "Two adults, one-night double booking",
        "assurance": "Room available at 14:00",
        "arrival": "14:00",
        "inspection_release": "15:24",
        "keys_handed_over": "15:26",
        "arrival_to_keys_minutes": 86,
        "keys_after_assured_time_minutes": 86,
