      }
    ]
  },
  "fictional_record_snippets": {
    "reading_rule": "When asked, identify the record as fictional and quote only the relevant contents. These are readable invented excerpts, not authentic exports or files.",
    "pms": {
      "kind": "Fictional PMS reservation and housekeeping excerpts",
      "exact_contents": [
        "19 Sep 09:10 | Room 06 departing reservation | MB: Late checkout approved to 13:00.",
        "19 Sep 13:07 | Room 06 | Departure checked out; housekeeping Dirty.",
        "19 Sep 14:00 | VC-0919-06 | Assigned room 06; housekeeping Dirty.",
        "19 Sep 14:22 | Room 11 | Housekeeping Clean | LM.",
        "19 Sep 15:29 | Room 06 | Housekeeping Clean | LM."
      ]
    },
    "whatsapp": {
      "kind": "Fictional staff WhatsApp thread",
      "exact_contents": [
        "19 Sep 07:12 Mariam: I'm sick and cannot come today. Sorry, Eka.",
        "19 Sep 11:56 Eka: Only Salome and me. 06 has late checkout. Cannot confirm 13:30 for 11 or 14:00 for 06. Which first?",
        "19 Sep 12:03 Nino: 11 first please. Both early arrivals in notebook.",
        "19 Sep 14:18 Eka: 11 checked, ready. 06 still being cleaned.",
        "19 Sep 15:24 Eka: 06 checked and ready. You can give keys."
      ],
      "limits": "No preserved read receipts establish when Luka saw the earlier warning. Nino's reply establishes awareness of pressure, not that she revised the guest assurances."
    },
    "notebook": {
      "kind": "Fictional front-desk notebook excerpts",
      "exact_contents": [
        "19/9 08:05 NK — 11 asks 13:30; 06 asks 14:00. Subject to HK.",
        "10:42 NK — 06 called. Told them 14:00 room available.",
        "10:48 NK — 11 confirmed 13:30 by phone.",
        "13:32 LM — 11 arrived. Waiting in courtyard.",
        "14:00 LM — 06 arrived. Says 14:00 was promised.",
        "14:20 LM — 11 keys given.",
        "15:26 LM — 06 keys given. Maia agreed 60 back + wine 30 waived."
      ],
      "limits": "The telephone wording is supported by Nino's own notes, not a recording. The guests' complete conversations are unavailable."
    },
    "folio": {
      "kind": "Fictional room 06 folio and cashbook excerpts",
      "exact_contents": [
        "VC-0919-06 | 18 Sep | Card payment received | 320.00 GEL",
        "VC-0919-06 | 19 Sep | One-night room charge | 320.00 GEL",
        "VC-0919-06 | 19 Sep | Reserved wine service for two | 30.00 GEL",
        "VC-0919-06 | 19 Sep 15:31 | Room service-recovery adjustment, MB | -60.00 GEL",
        "VC-0919-06 | 19 Sep 15:32 | Wine service waived, MB | -30.00 GEL",
        "VC-0919-06 | 19 Sep 15:34 | Cash refund paid | 60.00 GEL",
        "Cashbook 19 Sep 15:34 | OUT 60.00 GEL | VC-0919-06 refund | LM",
        "VC-0919-06 | Closing charges 260.00 GEL | Net payments retained 260.00 GEL | Balance 0.00 GEL"
      ]
    }
  },
